        "parts": "Nhíp, vỏ điện thoại và máy ảnh, vỏ thiết bị, khay chip, linh kiện điện tử, giấy đóng gói và linh kiện điện tử",
        "focus": "Vật liệu chống tĩnh điện vĩnh cửu dựa trên PC/ABS, sử dụng công nghệ biến đổi chống tĩnh điện polymer với hướng pha chế chống cháy. Hướng ứng dụng bao gồm nhíp, vỏ điện thoại và máy ảnh, vỏ thiết bị, khay chip, linh kiện điện tử, tấm đóng gói và linh kiện điện tử; xác nhận khả năng chịu và điều kiện gia công cho loại và chi tiết hoàn thiện.",
