      "profile": {
        "parts": "Bảng, tấm, băng keo, hồ sơ, nhíp, linh kiện điện tử, vỏ điện, thùng chứa và thiết bị truyền thông",
        "focus": "Vật liệu dẫn điện dựa trên PC, sử dụng công nghệ gia cường sợi carbon cho yêu cầu điện trở thấp. Hướng ứng dụng bao gồm bảng mạch, tấm, băng keo, thanh gọn, nhíp, linh kiện điện tử, vỏ điện, thùng chứa và thiết bị truyền thông; xác nhận điện trở và điều kiện gia công cho loại và chi tiết hoàn thiện.",
        "process": "Xác nhận độ khô, nhiệt độ nóng chảy, nhiệt độ khuôn và thời gian lưu trữ cho cấp độ; kiểm tra độ cản, hình thức và kích thước sau khi thử nghiệm.",
        "reinforcement": "Gia cường sợi carbon; xác nhận hàm lượng gia cường và công thức cho loại",
        "tests": [
          "Điện trở: xác định điện cực, điện áp kiểm tra, tình trạng mẫu, nhiệt độ và độ ẩm; kiểm tra cả mẫu vật liệu và các bộ phận đúc",
          "Hành vi dài hạn: đánh giá kiểm soát tĩnh sau khi điều kiện, làm sạch, mài mòn và lão hóa",
          "Xác thực chi tiết: đánh giá độ dày thành bột, hướng sợi, lắp ráp và nối đất trong ứng dụng dự kiến"
        ]
      },
