      "profile": {
        "parts": "Phụ tùng ô tô, vỏ điện và linh kiện điện tử",
        "focus": "Vật liệu chống tĩnh điện vĩnh cửu dựa trên PBT, sử dụng biến đổi chống tĩnh điện polymer với công nghệ gia cường sợi thủy tinh. Hướng ứng dụng bao gồm các bộ phận ô tô, vỏ điện và linh kiện điện tử; xác nhận điện trở và điều kiện gia công cho loại và chi tiết hoàn thiện.",
        "process": "Xác nhận độ khô, nhiệt độ nóng chảy, nhiệt độ khuôn và thời gian lưu trữ cho cấp độ; kiểm tra độ cản, hình thức và kích thước sau khi thử nghiệm.",
        "reinforcement": "Biến đổi chống tĩnh điện polymer với gia cường sợi thủy tinh; Xác nhận hàm lượng gia cường và công thức cho loại",
        "tests": [
          "Điện trở: xác định điện cực, điện áp kiểm tra, tình trạng mẫu, nhiệt độ và độ ẩm; kiểm tra cả mẫu vật liệu và các bộ phận đúc",
          "Hành vi dài hạn: đánh giá kiểm soát tĩnh sau khi điều kiện, làm sạch, mài mòn và lão hóa",
          "Xác thực chi tiết: đánh giá độ dày thành bột, hướng sợi, lắp ráp và nối đất trong ứng dụng dự kiến"
        ]
      },
